"""Render hand-authored legacy systems criteria without touching baseline records."""
from pathlib import Path
import argparse,hashlib,importlib,json,re,sys
ROOT=Path(__file__).resolve().parents[4]
HERE=Path(__file__).resolve().parent
sys.path.insert(0,str(HERE))
from technical_guidance import HINTS,ASSESSOR
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def write(p,v):
 p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
def meta(p):return json.loads(re.search(r'```json\s*\n(.*?)\n```',p.read_text(encoding='utf-8'),re.S)[1])
def pin(p,scope):return dict(path=p.relative_to(ROOT).as_posix(),sha256=hashlib.sha256(p.read_bytes()).hexdigest(),passages=[scope])
SOURCE_TOPICS={
 'T07':{'01':['GCC-STAGES'],'02':['GCC-STAGES','CMAKE-CROSS'],'03':['GCC-WARN','GCC-PRAGMA'],'04':['GCC-STAGES','GCC-LINK'],'05':['MAKE'],'06':['CMAKE-BUILD','CMAKE-PACKAGE'],'07':['MAKE','CMAKE-CROSS'],'08':['NINJA','COMPDB'],'09':['CMAKE-CROSS','AAPCS32'],'10':['CMAKE-PACKAGE'],'11':['GCC-WARN','CMAKE-CROSS'],'12':['GCC-STAGES']},
 'T08':{'01':['AMD64'],'02':['AMD64'],'03':['AMD64'],'04':['AMD64'],'05':['AMD64'],'06':['AAPCS32'],'07':['AMD64'],'08':['GCC-ASM'],'09':['SYSCALL'],'10':['GCC-STAGES','GCC-ASM']},
 'T09':{'01':['ELF'],'02':['ELF'],'03':['GCC-LINK'],'04':['ELF','GCC-LINK'],'05':['GCC-LINK'],'06':['DLOPEN'],'07':['DLOPEN','MUSL-START'],'08':['LD-LMA'],'09':['LD-KEEP','GCC-LINK'],'10':['LD-LMA','ELF'],'11':['DLOPEN','ELF'],'12':['ELF']},
 'T10':{'01':['AMD64','GLIBC-START'],'02':['AMD64'],'03':['GCC-LINK','GLIBC-START'],'04':['GLIBC-START','MUSL-START'],'05':['SYSCALL'],'06':['SYSCALL','GCC-ASM'],'07':['WRITE'],'08':['GCC-LINK'],'09':['GCC-LINK'],'10':['GLIBC-START','AMD64']},
 'T11':{str(n).zfill(2):['GCC-LINK','CLANG-FREE'] for n in range(1,11)},
}
def main(domains):
 resources={r['id']:r for r in read(HERE/'resources.json')['resources']}
 units=read(ROOT/'curriculum/v4/units.json')['units']
 for domain in domains:
  cards=importlib.import_module(domain.lower()+'_cards').rows()
  audit=[];all_ids=[]
  for project in sorted((ROOT/'curriculum/projects').glob('PR-'+domain+'-*.md')):
   m=meta(project);pid=m['id'];body=project.read_text(encoding='utf-8')
   objectives=dict(re.findall(r'- \[ \] `(T\d+\.\d+\.[a-z])`: (.*?) Link distinct',body))
   assert all(x in cards for x in objectives),(pid,set(objectives)-set(cards))
   pu=[u for u in units if u['project']==pid];tests=sorted({t for u in pu for t in u.get('tests',[])})
   module=ROOT/'curriculum/modules'/ (domain+'.md');fixture=ROOT/m['fixtures'][0]
   bindings=[pin(module,'Topic teaching passages and reading guidance for '+', '.join(m['topics'])),pin(project,'Contract, Steps, Failure cases, Acceptance and linked-objective checklist'),pin(fixture,'Complete synthetic fixture and expected values'),pin(ROOT/'tools/verify_systems_fixtures.py','oracle branches used by this fixture; synthetic reference is not target execution')]
   if domain=='T07':bindings.append(pin(ROOT/'labs/foundations/tests/negative_compile.py','Four positive/constraint compilation cases; no whole-build assessment'))
   else:
    for f,s in [('labs/machine_image/README.md','All twelve bounded laboratory contracts and explicit remaining obligations'),('labs/machine_image/tests/runtime.c','abi, hostile, bytes and wide cases'),('labs/machine_image/tests/artifacts.py','archive, relocation, tls, budget, entry, syscall, helpers, byte_closure, closure and image branches')]:bindings.append(pin(ROOT/f,s))
   source_ids=sorted({'R-LSYS-'+x for topic in m['topics'] for x in SOURCE_TOPICS[domain][topic.split('.')[1]]})
   sources=[dict(id=i,path='research/v5/expansion/legacy_systems/resources.json',passages=resources[i]['locators']) for i in source_ids]
   criteria=[];analysis=['# '+pid+' supplemental assessor analysis','','Assessor only. The accepted project remains the implementation contract. These arguments are authored technical expectations, not fresh experiment or learner evidence.','']
   for oid,title in objectives.items():
    row=cards[oid];row['hints']=list(HINTS[oid.rsplit('.',1)[0]]);row['assessor']=ASSESSOR.get(oid, 'Require the causal argument above and an independent artifact or trace that discriminates it from: '+row['misconception']);cid='AX-'+pid+'-'+oid;aid=oid.lower().replace('.','');task=row['task'];expected=row['expected'];variant=row['variant'];families=row.get('families',['A','D','F','I','J'])
    if any(x in task.lower() for x in ['implement','write ','build ','generate ','create ']) and 'B' not in families:families.insert(1,'B')
    criterion=dict(id=cid,title=title,objective=oid,families=families,task=task,purpose=row['misconception'],prerequisites=dict(knowledge=['The retained '+oid.rsplit('.',1)[0]+' teaching passage and parent project prerequisites','C17 semantics distinguished from the named tool/ABI/OS contract'],artifacts=[pid+' learner-owned implementation or diagnostic dossier','Predicted original fixture outcome before observing the expected data']),reasoning=[row['misconception']+' Supply the smallest counterexample or missing precondition.',row.get('reasoning','State the producer/consumer or ownership boundary, valid inputs, permitted side effects, failure behavior and resource model for this task.'),'The exact source/target assumptions and evidence limits must accompany the result.'],deliverables=dict(D1='A pre-experiment prediction and causal argument addressing: '+row['misconception'],D2=task,D3='Commands or derivation steps, original inputs, observed outputs, a minimized disagreement and an independent control for the criterion-specific expected result.',D4=variant),verification=dict(procedure=row.get('procedure','Predict first, execute or derive the task within its declared boundary, and compare every specified artifact/result. Retain positive and negative controls and identify launch/tool failures separately. Reuse the accepted fixture only for its stated synthetic model; add the task-specific cases above.'),expected=expected,**{'pass':'Meet every task clause and justify the expected argument using the actual artifact or trace. A matching result with an incorrect cause or undeclared dependency fails this objective.'},limits='Authored supplemental assessment; old laboratory names identify partial support only. No fresh execution, independent review, target availability or learner success is inferred.'),rubric={'0':'Missing artifact, incorrect expected result, unsafe precondition or false semantic claim.','1':'Reproduces the ordinary example but cannot reject the stated misconception or explain the boundary.','2':expected+' Supplies criterion-specific evidence and a distinct falsification control.','3':variant+' Derives the changed obligations independently after the recorded delay.'},hints=row.get('hints',['Locate the first producer, state transition or contract layer capable of causing the disagreement.','Compare the smallest two artifacts or states that differ; preserve the failure before applying the repair.']),variants=[dict(id=cid+'-DELAYED',minimum_days=7,task=variant)],assessor_anchor='#'+aid,facet_scope=dict(teaching='Retained substantive '+oid.rsplit('.',1)[0]+' module passage; scope bounded by the recorded inspection.',implementation_or_analysis='Retain '+pid+' construction and add this explicit per-leaf investigation; no duplicate executable unit claimed.',boundary_adversarial='The concrete changed, missing, incompatible or failure case in this task is assessed separately from the ordinary result.',independent_assessment='New objective-specific level2 criterion and seven-day changed-condition level3 variant; unattempted.',remaining='Learner execution/analysis, source-bound evidence review and delayed independent attempt remain required; listed source and target gaps stay open.'),security=dict(applicable=False,scope='Original learner programs and synthetic local artifacts only. No external target, privileged host action, real credential or other person data. ABI/UB-invalid cases are analysis or compile-only unless the parent supplies an explicitly contained original experiment.'))
    criteria.append(criterion);all_ids.append(oid)
    analysis+=['<a id="'+aid+'"></a>','## '+oid+' — '+title,'',expected,'','Reject superficial reasoning: '+row['misconception'],'','Discriminator: '+row.get('assessor','Ask the learner to identify the first artifact or state that contradicts the mistaken explanation, then explain why a passing ordinary case cannot exclude it.'),'','Delayed assessor check: '+variant,'']
   record=dict(schema_version=1,project=pid,domain=domain,title=m['title']+' — explicit depth assessments',shared_contracts=['curriculum/v5/expansion/legacy_assessments/shared-contract.md'],baseline_binding=dict(files=bindings,teaching=[dict(path=module.relative_to(ROOT).as_posix(),anchors=m['topics'])],units=[u['id'] for u in pu],inspection_limits=['Project contract/steps/checklists and module teaching inspected; source registers are not treated as actual book inspections.','Unit objective/test links and selected operation steps inspected; no fresh complete historical portfolio review.','No new execution or independent learner assessment in this authoring wave.']),environment=dict(language='Active C17 baseline. C11/C23 comparisons require their explicitly identified wording; GNU assembly, __int128, ELF and operating-system contracts are extensions/platform rules.',target='Linux x86-64 SysV for executable host observations; foreign targets are compile/analysis-only unless explicitly supported and recorded.',profile=m['profile'],dependencies='Retain the parent profile exactly. Host Python, build and binary inspection tools remain outside restricted target closures; no library may implement the mechanism being taught.',toolchain=['Record GCC/Clang, CMake/Ninja/Make and binutils versions and effective flags','Unsupported target or instrumentation cells remain unavailable']),source_records=sources,reference_gaps=['Exact published C17/C23 text and private CS:APP/TLPI passages were not newly inspected.','Primary sources listed cover only the named passages; other parent references retain their historical status without a new inspection claim.']+(['Current full ELF gABI and historical AMD64 0.99 PDF fetch unavailable; full loader/TLS implementation and selected library service contracts remain required for claims beyond supplied passages.'] if domain in ['T08','T09','T10','T11'] else []),supplied_artifacts=[project.relative_to(ROOT).as_posix(),fixture.relative_to(ROOT).as_posix(),'tools/verify_systems_fixtures.py'],execution_support=dict(kind='retained partial baseline laboratory anchors' if tests else 'retained implementation/analysis contract with synthetic fixture',scope='Tests exercise only their named bounded cases; broad project acceptance and these supplemental criteria require separate evidence.',tests=tests,fresh_execution='not-run in this depth-authoring wave'),criteria=criteria,assessor_analysis='assessor/legacy_depth/'+pid+'.md',status=dict(content='authored',execution='not-run supplemental assessments',independent_review='not-run',learner_assessment='not-assessed',limitations=['Finite visible tests are not absolute mastery.','No baseline hours, IDs, source bytes or historical acceptance receipts changed.']))
   audit.append(dict(project=pid,objectives=list(objectives),baseline_bindings=bindings,teaching='substantive retained passage',construction='retained concrete project contract',boundary='bounded named baseline tests plus broader stated project cases',independent_assessment_before='topic acceptance/checklist and general transfer; no explicit per-leaf 0-3 rubric',expansion='Add '+str(len(criteria))+' distinct per-leaf investigations/rubrics/delayed variants',tests=tests,fixture_limit=read(fixture)['oracle_type']+' synthetic oracle; not real platform coverage'))
   # Audit entry is written before publishing the authored supplement.
   write(HERE/(domain+'_audit.json'),dict(domain=domain,status='author depth audit',projects=audit,limitations=['Bounded repository passage review; no independent review or fresh baseline run.']))
   write(ROOT/'curriculum/v5/expansion/legacy_assessments'/ (pid+'.json'),record)
   ap=ROOT/record['assessor_analysis'];ap.parent.mkdir(parents=True,exist_ok=True);ap.write_text('\n'.join(analysis)+'\n',encoding='utf-8',newline='\n')
  assert set(all_ids)==set(cards),(domain,set(cards)-set(all_ids))
  write(HERE/(domain+'_remaining.json'),dict(domain=domain,authored_criteria=len(all_ids),required=True,pending=[dict(objective=o,work='Execute/derive and assess the criterion, then perform its delayed transfer',status='unattempted') for o in all_ids],external=['Published ISO editions and uninspected private corpus passages remain reference gaps.','Unsupported targets require actual availability; no physical validation inferred.']))
  print(domain,len(audit),'projects',len(all_ids),'criteria authored')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('domains',nargs='+');main(p.parse_args().domains)
